{
  "info": {
    "title": "UAE Payment API",
    "description": "## UAE Open Finance Payment API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/payment/v2.2"
    }
  ],
  "source_path": "/payment-consents/{ConsentId}/attestations",
  "operations": {
    "post": {
      "operationId": "CreatePaymentConsentAttestation",
      "summary": "Create an attestation",
      "description": "Create an Attestation against a consent for a given `ConsentId`.\n\nThe consent must be in the `Revoked`, `Expired` or `Consumed` terminal status. Each Attestation\nEvent is an atomic event that is not correlated with other Attestation Events of the same type.",
      "parameters": [
        {
          "$ref": "#/components/parameters/authorization"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id-request"
        },
        {
          "$ref": "#/components/parameters/ConsentId"
        }
      ],
      "responses": {
        "201": {
          "description": "The request has succeeded and a new resource has been created as a result.",
          "headers": {
            "x-fapi-interaction-id": {
              "required": false,
              "description": "An RFC4122 UID used as a correlation ID.",
              "schema": {
                "type": "string"
              }
            }
          },
          "content": {
            "application/jwt": {
              "schema": {
                "$ref": "#/components/schemas/AETPPAttestationSigned1Response"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "tags": [
        "Consent"
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/jwt": {
            "schema": {
              "$ref": "#/components/schemas/AECreateTPPAttestationSigned1Request"
            }
          }
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "payments"
          ]
        }
      ]
    }
  }
}

